protected LivingEntity pickTarget(ServerWorld world, BlockPos pos) {
	Box box = new Box(pos).expand(range);
	LivingEntity bestPlayer = null;
	LivingEntity bestOther = null;
	double bestP = Double.MAX_VALUE, bestO = Double.MAX_VALUE;
	Vec3d origin = Vec3d.ofCenter(pos);
	for (LivingEntity e : world.getEntitiesByClass(LivingEntity.class, box, this::isValidTarget)) {
		double d = e.squaredDistanceTo(origin);
		if (e instanceof PlayerEntity) {
			if (d < bestP) { bestP = d; bestPlayer = e; }
		} else if (d < bestO) {
			bestO = d;
			bestOther = e;
		}
	}
	return bestPlayer != null ? bestPlayer : bestOther;
}

protected boolean isValidTarget(LivingEntity e) {
	if (!e.isAlive()) return false;
	if (e instanceof EndReactorBossEntity) return false;
	if (e instanceof ReactorKeeperEntity) return false;
	if (e instanceof PlayerEntity p && (p.isCreative() || p.isSpectator())) return false;
	return true;

	private void dispenseCluster(ServerWorld sw) {
        if(dispensed || submunition || isRemoved())return;
        int count=type.heavyCluster?14:7;
        var budget=BURST_BUDGETS.computeIfAbsent(sw,key->new ClusterBurstBudget());
        if(!budget.reserve(sw.getServer().getTicks(),net.minecraft.util.math.ChunkPos.toLong(getBlockPos().getX()>>4,getBlockPos().getZ()>>4),count,()->{
            int live=0;
            for(var entity:sw.iterateEntities())if(entity instanceof AerialBombEntity bomb && bomb.submunition && !bomb.isRemoved()) {
                if(++live>=ClusterBurstBudget.MAX_LIVE)break;
            }
            return live;
        })) {landed=true;return;}
        dispensed=true;
        Random rng=sw.getRandom();
		float outward = type.heavyCluster ? 1.25f : 0.62f;
		float fragBlast = type.heavyCluster ? 0.95f : 0.58f;
		Vec3d parentVel = getVelocity();
		Vec3d fallAxis = parentVel.lengthSquared() > 1e-4
				? parentVel.normalize()
				: gravityDir();
		// Pole-safe lateral basis for the cone (no world-up cross).
		Vec3d right = com.terminaldetector.drmd.flight.ShipAttitude.levelRightOf(fallAxis);
		Vec3d up = right.crossProduct(fallAxis).normalize();

		float opener = AtmosphereRules.scaleBlast(getY(), 2.4f * type.blastPower);
		sw.createExplosion(this, getX(), getY(), getZ(), opener * 0.55f, true, World.ExplosionSourceType.TNT);
		SmokeSystem.emitExplosion(getPos(), opener);

		for (int i = 0; i < count; i++) {
			Vec3d dir;
			if (type.heavyCluster) {
				dir = randomUnit(rng);
			} else {
				// Cone along fall axis with lateral scatter in ship-safe basis.
				dir = fallAxis
						.add(right.multiply((rng.nextDouble() - 0.5) * 1.4))
						.add(up.multiply((rng.nextDouble() - 0.5) * 1.4))
						.add(fallAxis.multiply(0.35 + rng.nextDouble() * 0.55))
						.normalize();
			}
			double speed = outward * (0.75 + rng.nextDouble() * 0.55);
			Vec3d fragVel = parentVel.multiply(0.55).add(dir.multiply(speed));
			AerialBombEntity frag = ModEntities.AERIAL_BOMB.create(sw);
			if (frag == null) continue;
			// No Euler pitch=90 — orientation is implied by velocity for tracers/mesh.
			frag.refreshPositionAndAngles(
					getX() + dir.x * 0.35,
					getY() + dir.y * 0.35,
					getZ() + dir.z * 0.35,
					0f, 0f);
			frag.setVelocity(fragVel);
			frag.configureSubmunition(this.type, ownerId, fragBlast, fragVel);
            frag.launchDown=gravityDir();
            if(!sw.isChunkLoaded(frag.getBlockPos()) || !sw.isSpaceEmpty(frag,frag.getBoundingBox()))frag.setPosition(getPos());
			sw.spawnEntity(frag);
		}
		discard();

package com.terminaldetector.drmd.world.geometry;

import net.minecraft.block.*;
import net.minecraft.registry.tag.BlockTags;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.shape.*;
import net.minecraft.world.BlockView;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/** Non-destructive adapter: vanilla states, growth, drops and saves retain their identity. */
public final class NaturalGeometry {
    private NaturalGeometry() {}
    private static final Set<Block> GROUND=Set.of(Blocks.STONE,Blocks.GRANITE,Blocks.DIORITE,
        Blocks.ANDESITE,Blocks.DEEPSLATE,Blocks.TUFF,Blocks.CALCITE,Blocks.DIRT,Blocks.GRASS_BLOCK,
        Blocks.COARSE_DIRT,Blocks.ROOTED_DIRT,Blocks.PODZOL,Blocks.MYCELIUM,Blocks.CLAY,
        Blocks.SAND,Blocks.RED_SAND,Blocks.GRAVEL,Blocks.NETHERRACK,Blocks.END_STONE,
        Blocks.TERRACOTTA,Blocks.SNOW_BLOCK,Blocks.MOSS_BLOCK);
    private static final ConcurrentHashMap<HybridMesh.Neighbourhood,VoxelShape> SHAPES=new ConcurrentHashMap<>();
    public static boolean applies(BlockState state) {
        return GROUND.contains(state.getBlock()) || state.isIn(BlockTags.LOGS) || state.isIn(BlockTags.LEAVES);
    }
    public static VoxelShape shape(BlockState state,BlockView world,BlockPos pos) {
        var key=HybridTerrain.snapshot(world,pos,new HybridTerrain.Data(state,-1L,true));
        return shape(key);
    }
    public static VoxelShape shape(HybridMesh.Neighbourhood key) {
        var cached=SHAPES.get(key);if(cached!=null)return cached;
        var shape=BoundedHybridShape.from(new HybridMesh(key).collisionBounds());
        if(SHAPES.size()<4096)SHAPES.putIfAbsent(key,shape);
        return shape;
    }
}

